import { readFileSync } from "node:fs";
import path from "node:path";
import tailwindcss from "@tailwindcss/postcss";
import react from "@vitejs/plugin-react";
import autoprefixer from "autoprefixer";
import type { Plugin } from "postcss";
import { defineConfig, type Plugin as VitePlugin } from "vite";
import { viteSingleFile } from "vite-plugin-singlefile";

/**
 * Build for MCP App UI resources — sandboxed-iframe payloads served from `ui://`
 * resources and rendered by MCP Apps hosts (Slackbot, Claude, or our own web
 * UI). Distinct from the SPA build (`vite.config.ts`): no router, one small
 * HTML template plus stable JS/CSS assets per app, reusing the SPA's
 * shadcn components + Tailwind v4 theme (each entry's `app.css` →
 * `../../index.css`). The server stamps the serving origin into the template
 * before returning it from `resources/read`.
 *
 * One app builds per invocation, selected by `MCP_APP` (defaults to
 * `interaction`, the single data-driven bundle). `build:mcp-apps` runs this once
 * per app under `src/mcp-apps/`.
 */
const app = process.env.MCP_APP?.trim() || "interaction";
const legacy = process.env.MCP_APP_LEGACY === "1";
const sharedStylesheetPath = path.resolve(__dirname, "src/index.css");
const appStylesheetPath = path.resolve(
	__dirname,
	"src/mcp-apps",
	app,
	"app.css",
);
const omitExternalFontFaces: Plugin = {
	postcssPlugin: "mcp-app-omit-external-font-faces",
	AtRule: {
		"font-face": (rule) => rule.remove(),
	},
};

/**
 * Keep the shared theme as the source of truth, but narrow Tailwind's class
 * discovery to the MCP app dependency surface. The SPA stylesheet explicitly
 * scans the entire package and server public pages; carrying those unrelated
 * utilities in a resources/read response wastes the embedding host's payload
 * budget.
 */
const narrowTailwindSources: VitePlugin = {
	name: "mcp-app-narrow-tailwind-sources",
	enforce: "pre",
	transform(source, id) {
		const filename = id.split("?", 1)[0];
		if (path.resolve(filename) !== appStylesheetPath) return null;
		const sharedTheme = readFileSync(sharedStylesheetPath, "utf8")
			.replace(
				"@import 'tailwindcss' source('..');",
				"@import 'tailwindcss' source(none);",
			)
			.replace(/^@import\s+['"]\.\/fonts\.css['"];\s*$/gm, "")
			.replace(/^@source\s+[^;]+;\s*$/gm, "");
		return source.replace('@import "../../index.css";', sharedTheme);
	},
};

const legacySelfContainedCsp: VitePlugin = {
	name: "mcp-app-legacy-self-contained-csp",
	enforce: "pre",
	transformIndexHtml(html) {
		if (!legacy) return html;
		return html.replace(
			"default-src 'none'; script-src __LOBU_MCP_APP_ORIGIN__; style-src 'unsafe-inline' __LOBU_MCP_APP_ORIGIN__; img-src data: blob: __LOBU_MCP_APP_ORIGIN__; connect-src 'none'; font-src 'none'; media-src 'none'; object-src 'none'; frame-src 'none'; base-uri __LOBU_MCP_APP_ORIGIN__; form-action 'none'",
			"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data: blob:; connect-src 'none'; font-src 'none'; media-src 'none'; object-src 'none'; frame-src 'none'; base-uri 'none'; form-action 'none'",
		);
	},
};

/**
 * ChatGPT embeds MCP App resources on a different origin. Its sandbox accepts
 * scripts from the declared resource domain, but cross-origin ES modules are
 * not consistently executed. The hosted bundle is already a single entry, so
 * emit it as an IIFE and load it as a classic deferred script. This preserves
 * the small external template without relying on module loading semantics.
 */
const externalClassicScript: VitePlugin = {
	name: "mcp-app-external-classic-script",
	transformIndexHtml: {
		order: "post",
		handler(html) {
			if (legacy) return html;
			return html.replace(
				/<script type="module" crossorigin src="(\.\/assets\/app\.js)"><\/script>/,
				'<script defer src="$1"></script>',
			);
		},
	},
};

export default defineConfig({
	root: path.resolve(__dirname, "src/mcp-apps", app),
	base: legacy ? undefined : "./",
	css: {
		postcss: {
			plugins: [tailwindcss(), autoprefixer(), omitExternalFontFaces],
		},
	},
	resolve: { alias: { "@": path.resolve(__dirname, "./src") } },
	build: {
		target: "esnext",
		outDir: path.resolve(
			__dirname,
			"dist-mcp-apps",
			legacy ? `${app}-legacy` : app,
		),
		emptyOutDir: true,
		cssCodeSplit: false,
		rollupOptions: legacy
			? undefined
			: {
					output: {
						format: "iife",
						// Stable paths are deliberate: every replica in a rolling deployment
						// must serve the URLs captured in cached HTML. A post-build step adds
						// content-derived query versions so browser caches cannot reuse stale bytes.
						assetFileNames: "assets/app.[ext]",
						entryFileNames: "assets/app.js",
						inlineDynamicImports: true,
					},
				},
	},
	plugins: [
		narrowTailwindSources,
		legacySelfContainedCsp,
		react(),
		externalClassicScript,
		...(legacy ? [viteSingleFile()] : []),
	],
});

