import { App, PostMessageTransport } from "@modelcontextprotocol/ext-apps";
import {
	createContext,
	type FC,
	type ReactNode,
	useCallback,
	useContext,
	useEffect,
	useRef,
	useState,
} from "react";
import { createRoot } from "react-dom/client";
import {
	approvalCapabilityFromMeta,
	persistOpenAiViewSnapshot,
	readOpenAiCompatSnapshot,
	snapshotCapabilityFromOpenAiGlobals,
} from "./openai-compat";
import { isExternalHttpUrl } from "./view";

/** Shared iframe-side runtime for every Lobu MCP App bundle. */

type ToolArgs = Record<string, unknown>;
type ViewStateValue = boolean | number | string;
type McpAppViewState = Record<string, ViewStateValue>;

interface McpAppApi<T> {
	/** Server-authored LobuViewV1 from the originating tool result. */
	data: T | null;
	/** Originating MCP tool name, supplied by the standard host context. */
	toolName: string | null;
	/** Small restored pagination/disclosure state for this exact result card. */
	viewState: McpAppViewState;
	setViewState: (key: string, value: ViewStateValue) => void;
	/** Ask the host to broker a standard MCP `tools/call`. */
	callTool: (name: string, args: ToolArgs) => Promise<void>;
	/** Ask the host to open an external URL via `ui/open-link`. */
	openLink: (href: string) => Promise<void>;
	/** Latest app-initiated tool result; `seq` bumps so effects react to retries. */
	lastResult: { isError: boolean; seq: number } | null;
	/** True only inside Lobu's same-origin SPA parent, never in an external host. */
	allowSpaHostedViews: boolean;
}

const McpAppContext = createContext<McpAppApi<unknown>>({
	data: null,
	toolName: null,
	viewState: {},
	setViewState: () => {},
	callTool: async () => {},
	openLink: async () => {},
	lastResult: null,
	allowSpaHostedViews: false,
});

/** Typed accessor for the host bridge inside a bundle's card component. */
export function useMcpApp<T>(): McpAppApi<T> {
	return useContext(McpAppContext) as McpAppApi<T>;
}

const isEmbedded = window.parent !== window;
const OPENAI_SET_GLOBALS_EVENT = "openai:set_globals";

type OpenAiCompatWindow = Window & { openai?: unknown };
type OpenAiSetGlobalsEvent = CustomEvent<{ globals?: unknown }>;

function openAiCompatTargets(): OpenAiCompatWindow[] {
	const ownWindow = window as OpenAiCompatWindow;
	if (!isEmbedded) return [ownWindow];
	try {
		if (window.parent.location.origin === window.location.origin) {
			return [ownWindow, window.parent as OpenAiCompatWindow];
		}
	} catch {
		// A cross-origin parent is the standard portable MCP Apps topology.
	}
	return [ownWindow];
}

function currentOpenAiGlobals(targets = openAiCompatTargets()): unknown {
	let fallback: unknown;
	let metadataFallback: unknown;
	let widgetStateFallback: unknown;
	for (const target of targets) {
		const candidate = target.openai;
		if (candidate === undefined) continue;
		fallback ??= candidate;
		if (
			isStructuredObject(candidate) &&
			Object.hasOwn(candidate, "toolOutput")
		) {
			return candidate;
		}
		if (
			isStructuredObject(candidate) &&
			readOpenAiCompatSnapshot(candidate).data !== undefined
		) {
			widgetStateFallback ??= candidate;
		}
		if (
			isStructuredObject(candidate) &&
			Object.hasOwn(candidate, "toolResponseMetadata")
		) {
			metadataFallback ??= candidate;
		}
	}
	return widgetStateFallback ?? metadataFallback ?? fallback;
}

function persistOpenAiData<T>(
	targets: OpenAiCompatWindow[],
	data: T | null,
): void {
	for (const target of targets) {
		if (persistOpenAiViewSnapshot(target.openai, data)) return;
	}
}

function hasSameOriginParent(): boolean {
	if (!isEmbedded) return true;
	try {
		return window.parent.location.origin === window.location.origin;
	} catch {
		return false;
	}
}

function isStructuredObject(value: unknown): value is Record<string, unknown> {
	return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function hasResultData(value: unknown): value is Record<string, unknown> {
	return isStructuredObject(value) && Object.keys(value).length > 0;
}

function toolInfoFromHostContext(value: unknown): {
	id: string | number;
	name: string;
} | null {
	if (!isStructuredObject(value) || !isStructuredObject(value.toolInfo))
		return null;
	const id = value.toolInfo.id;
	const tool = value.toolInfo.tool;
	if (
		(typeof id !== "string" && typeof id !== "number") ||
		!isStructuredObject(tool) ||
		typeof tool.name !== "string"
	) {
		return null;
	}
	return { id, name: tool.name };
}

function snapshotCapabilityFromMeta(value: unknown): string | null | undefined {
	if (
		!isStructuredObject(value) ||
		!Object.hasOwn(value, "lobu/mcp-app-snapshot-capability")
	)
		return undefined;
	const capability = value["lobu/mcp-app-snapshot-capability"];
	if (typeof capability !== "string") return null;
	const normalized = capability.trim();
	return normalized && normalized.length <= 512 ? normalized : null;
}

function restoredViewState(value: unknown): McpAppViewState {
	if (!isStructuredObject(value)) return {};
	return Object.fromEntries(
		Object.entries(value).filter(
			(entry): entry is [string, ViewStateValue] =>
				typeof entry[1] === "boolean" ||
				typeof entry[1] === "string" ||
				(typeof entry[1] === "number" && Number.isFinite(entry[1])),
		),
	);
}

function sameViewState(
	left: McpAppViewState,
	right: McpAppViewState,
): boolean {
	const leftKeys = Object.keys(left);
	const rightKeys = Object.keys(right);
	return (
		leftKeys.length === rightKeys.length &&
		leftKeys.every((key) => left[key] === right[key])
	);
}

function resultDataFingerprint(value: unknown): string | null {
	try {
		return (
			JSON.stringify(value, (_key, nested) =>
				isStructuredObject(nested)
					? Object.fromEntries(
							Object.entries(nested).sort(([left], [right]) =>
								left.localeCompare(right),
							),
						)
					: nested,
			) ?? null
		);
	} catch {
		return null;
	}
}

function applyTheme(theme: "light" | "dark" | undefined): void {
	const dark = theme
		? theme === "dark"
		: window.matchMedia("(prefers-color-scheme: dark)").matches;
	document.documentElement.classList.toggle("dark", dark);
}

export function Provider<T>({
	devMock,
	children,
}: {
	devMock: T;
	children: ReactNode;
	children: ReactNode;
}) {
	const [initialCompat] = useState(() =>
		readOpenAiCompatSnapshot<T>(currentOpenAiGlobals()),
	);
	const initialData = hasResultData(initialCompat.data)
		? (initialCompat.data as T)
		: null;
	const [data, setData] = useState<T | null>(
		isEmbedded ? initialData : devMock,
	);
	const [toolName, setToolName] = useState<string | null>(null);
	const [viewState, setViewStateValue] = useState<McpAppViewState>({});
	const [lastResult, setLastResult] = useState<{
		isError: boolean;
		seq: number;
	} | null>(null);
	const [app, setApp] = useState<App | null>(null);
	const [approvalCapability, setApprovalCapability] = useState<string | null>(
		initialCompat.approvalCapability ?? null,
	);
	const hasLiveToolOutput = useRef(false);
	const hasCurrentLifetimeToolResult = useRef(false);
	const hasData = useRef(data !== null);
	const resultExplicitlyCleared = useRef(false);
	const dataRevision = useRef(data === null ? 0 : 1);
	const toolCallId = useRef<string | number | null>(null);
	const toolCallName = useRef<string | null>(null);
	const snapshotCapability = useRef<string | null>(null);
	const snapshotSaveInFlight = useRef(false);
	const snapshotSavedKey = useRef<string | null>(null);
	const snapshotRestores = useRef(new Map<string, Promise<boolean>>());
	const snapshotRestoreCompleted = useRef(new Set<string>());
	const resultCapabilityIdentity = useRef<string | null>(null);
	const displayedDataFingerprint = useRef(
		initialData === null ? null : resultDataFingerprint(initialData),
	);
	const viewStateRef = useRef<McpAppViewState>({});
	const viewStateRevision = useRef(0);
	const persistSnapshotStateRef = useRef<(() => void) | null>(null);
	const saveStateTimer = useRef<number | null>(null);
	const allowSpaHostedViews = hasSameOriginParent();
	const resetResultViewState = useCallback(() => {
		if (saveStateTimer.current !== null) {
			window.clearTimeout(saveStateTimer.current);
			saveStateTimer.current = null;
		}
		snapshotSavedKey.current = null;
		snapshotRestores.current.clear();
		snapshotRestoreCompleted.current.clear();
		viewStateRef.current = {};
		viewStateRevision.current = 0;
		setViewStateValue({});
	}, []);

	useEffect(() => {
		if (!isEmbedded) {
			applyTheme(undefined);
			return;
		}

		const compatTargets = openAiCompatTargets();
		const nextApp = new App(
			{ name: "Lobu Interaction", version: "1.0.0" },
			{},
			{ autoResize: true, strict: true },
		);
		const transport = new PostMessageTransport(window.parent, window.parent);
		let connected = false;
		const snapshotStateKey = (
			id: string | number | null,
			name: string | null,
			capability: string | null,
			revision: number,
		) => JSON.stringify([id, name, capability, revision]);
		const persistSnapshotState = async () => {
			const activeRestore = snapshotRestores.current.get(
				JSON.stringify([
					toolCallId.current,
					toolCallName.current,
					snapshotCapability.current,
				]),
			);
			if (activeRestore) {
				// A user can change disclosure or pagination state while hydration is
				// still in flight. Never let the partial local map replace untouched
				// persisted keys before the restore has merged them.
				if (await activeRestore) await persistSnapshotState();
				return;
			}
			const capability = snapshotCapability.current;
			const id = toolCallId.current;
			const name = toolCallName.current;
			const revision = viewStateRevision.current;
			const stateKey = snapshotStateKey(id, name, capability, revision);
			if (
				(id === null && !capability) ||
				(!capability && revision === 0) ||
				snapshotSaveInFlight.current ||
				snapshotSavedKey.current === stateKey
			)
				return;
			snapshotSaveInFlight.current = true;
			try {
				const result = await nextApp.callServerTool({
					name: "save_lobu_app_state",
					arguments: {
						...(id === null ? {} : { tool_call_id: id }),
						...(name ? { tool_name: name } : {}),
						view_state: viewStateRef.current,
						...(capability ? { snapshot_capability: capability } : {}),
					},
					...(capability
						? {
								_meta: {
									"lobu/mcp-app-snapshot-capability": capability,
								},
							}
						: {}),
				});
				const saved =
					result.isError !== true &&
					isStructuredObject(result.structuredContent) &&
					result.structuredContent.saved === true;
				if (
					saved &&
					snapshotCapability.current === capability &&
					toolCallId.current === id &&
					toolCallName.current === name &&
					viewStateRevision.current === revision
				) {
					if (capability && id !== null) {
						// A standard host card id is sufficient for later state writes. Hosts
						// without toolInfo keep the scoped capability in iframe memory.
						snapshotCapability.current = null;
					}
					snapshotSavedKey.current = snapshotStateKey(
						toolCallId.current,
						toolCallName.current,
						snapshotCapability.current,
						viewStateRevision.current,
					);
				}
			} catch {
				console.warn("[mcp-app] failed to save result snapshot state");
			} finally {
				snapshotSaveInFlight.current = false;
				const latestKey = snapshotStateKey(
					toolCallId.current,
					toolCallName.current,
					snapshotCapability.current,
					viewStateRevision.current,
				);
				if (
					(toolCallId.current !== null || snapshotCapability.current) &&
					latestKey !== stateKey &&
					snapshotSavedKey.current !== latestKey
				) {
					// Result metadata, host identity, and UI state can change in either order.
					// Serialize them, then retry only the newest state after this save settles.
					void persistSnapshotState();
				}
			}
		};
		persistSnapshotStateRef.current = () => void persistSnapshotState();
		const restoreSnapshot = (options?: {
			allowDataPresent?: boolean;
		}): Promise<boolean> => {
			const allowDataPresent = options?.allowDataPresent === true;
			if (
				(hasData.current && !allowDataPresent) ||
				resultExplicitlyCleared.current
			)
				return Promise.resolve(false);
			const capability = snapshotCapability.current;
			const id = toolCallId.current;
			const name = toolCallName.current;
			const dataRevisionAtStart = dataRevision.current;
			const viewStateRevisionAtStart = viewStateRevision.current;
			if (id === null && !capability) return Promise.resolve(false);
			const restoreKey = JSON.stringify([id, name, capability]);
			const activeRestore = snapshotRestores.current.get(restoreKey);
			if (activeRestore) return activeRestore;
			if (snapshotRestoreCompleted.current.has(restoreKey)) {
				return Promise.resolve(true);
			}
			const restore = Promise.resolve().then(async () => {
				try {
					const result = await nextApp.callServerTool({
						name: "restore_lobu_app_result",
						arguments: {
							...(id === null ? {} : { tool_call_id: id }),
							...(name ? { tool_name: name } : {}),
							...(capability ? { snapshot_capability: capability } : {}),
						},
					});
					if (
						(!allowDataPresent && hasData.current) ||
						(dataRevision.current !== dataRevisionAtStart &&
							(!allowDataPresent || capability === null)) ||
						snapshotCapability.current !== capability ||
						toolCallId.current !== id ||
						toolCallName.current !== name
					) {
						return false;
					}
					if (!isStructuredObject(result.structuredContent)) return false;
					const restored = result.structuredContent;
					if (restored.found === false) {
						snapshotRestoreCompleted.current.add(restoreKey);
						return true;
					}
					if (restored.found !== true || !hasResultData(restored.data))
						return false;
					snapshotRestoreCompleted.current.add(restoreKey);
					const nextData = restored.data as T;
					const restoredState = restoredViewState(restored.view_state);
					const currentState = viewStateRef.current;
					const changedDuringRestore =
						viewStateRevision.current !== viewStateRevisionAtStart;
					const hasLocalViewState =
						viewStateRevisionAtStart > 0 || changedDuringRestore;
					const nextViewState = hasLocalViewState
						? { ...restoredState, ...currentState }
						: restoredState;
					viewStateRef.current = nextViewState;
					setViewStateValue(nextViewState);
					if (
						hasLocalViewState &&
						!sameViewState(currentState, nextViewState)
					) {
						// The merged value differs from the partial edit that may already be
						// queued for persistence, so give it a fresh serialized save key.
						viewStateRevision.current += 1;
					}
					if (!hasData.current) {
						dataRevision.current += 1;
						hasData.current = true;
						displayedDataFingerprint.current =
							resultDataFingerprint(nextData);
						setData(nextData);
						persistOpenAiData(compatTargets, nextData);
					}
					if (typeof restored.tool_name === "string") {
						toolCallName.current = restored.tool_name;
						setToolName(restored.tool_name);
					}
					return true;
				} catch {
					console.warn("[mcp-app] failed to restore result snapshot");
					return false;
				} finally {
					if (snapshotRestores.current.get(restoreKey) === restore) {
						snapshotRestores.current.delete(restoreKey);
					}
				}
			});
			snapshotRestores.current.set(restoreKey, restore);
			return restore;
		};
		const shouldPersistAfterRestore = () =>
			hasLiveToolOutput.current || viewStateRevision.current > 0;
		const capabilityChangesResult = (
			capability: string | null | undefined,
		) =>
			typeof capability === "string" &&
			resultCapabilityIdentity.current !== null &&
			capability !== resultCapabilityIdentity.current;
		const resetCurrentResult = () => {
			resetResultViewState();
			hasLiveToolOutput.current = false;
			hasCurrentLifetimeToolResult.current = false;
			hasData.current = false;
			resultExplicitlyCleared.current = false;
			dataRevision.current += 1;
			toolCallId.current = null;
			toolCallName.current = null;
			snapshotCapability.current = null;
			resultCapabilityIdentity.current = null;
			displayedDataFingerprint.current = null;
			setData(null);
			setToolName(null);
			setApprovalCapability(null);
			setLastResult(null);
		};
		const onToolResult = (params: {
			structuredContent?: unknown;
			_meta?: unknown;
		}) => {
			const capability = snapshotCapabilityFromMeta(params._meta);
			const hasLiveData = hasResultData(params.structuredContent);
			const capabilityChanged = capabilityChangesResult(capability);
			const repeatsCurrentCapability =
				typeof capability === "string" &&
				capability === resultCapabilityIdentity.current;
			const startsNewResult =
				capabilityChanged ||
				(hasLiveData &&
					hasCurrentLifetimeToolResult.current &&
					!repeatsCurrentCapability);
			if (startsNewResult) {
			if (startsNewResult) {
				// A new result delivered into a reused iframe owns a new view-state map.
				// The opaque capability is the result identity when toolInfo is absent.
				resetCurrentResult();
			}
			if (hasLiveData || capability !== undefined) {
				snapshotCapability.current = capability ?? null;
			}
			if (capabilityChanged && !hasLiveData) {
				// An empty replay can still identify a different result. Clear the old
				// card before restoring the new result through its opaque capability.
				resultCapabilityIdentity.current = capability as string;
				hasCurrentLifetimeToolResult.current = true;
				persistOpenAiData(compatTargets, null);
			}
			if (hasLiveData) resultExplicitlyCleared.current = false;
			if (hasLiveData) {
				const nextData = params.structuredContent as T;
				resultCapabilityIdentity.current = capability ?? null;
				hasLiveToolOutput.current = true;
				hasCurrentLifetimeToolResult.current = true;
				dataRevision.current += 1;
				hasData.current = true;
				displayedDataFingerprint.current =
					resultDataFingerprint(nextData);
				setData(nextData);
				persistOpenAiData(compatTargets, nextData);
				if (snapshotCapability.current) {
					// A standard host may replay the original non-empty result while
					// omitting toolInfo. Restore its saved disclosure/pagination state
					// before any capability-backed save can replace that state.
					void restoreSnapshot({ allowDataPresent: true }).then((restored) => {
						if (restored) void persistSnapshotState();
					});
				} else {
					void persistSnapshotState();
				}
			} else {
				// ChatGPT can replay an empty structuredContent object after a full
				// conversation reload while retaining result metadata. Restore the
				// exact display-only result through its scoped opaque capability.
				void restoreSnapshot();
			}
			setApprovalCapability(approvalCapabilityFromMeta(params._meta));
		};
		const onHostContext = (params: { theme?: "light" | "dark" }) => {
			applyTheme(params.theme);
			const info = toolInfoFromHostContext(nextApp.getHostContext());
			if (info) {
				const previousId = toolCallId.current;
				const identityChanged =
					toolCallId.current !== info.id || toolCallName.current !== info.name;
				const switchedCards = previousId !== null && previousId !== info.id;
				if (switchedCards) {
					// Host card ids are result identities. A reused iframe must not carry
					// data, capabilities, or UI state from the previous card into the next.
					resetResultViewState();
					hasLiveToolOutput.current = false;
					hasCurrentLifetimeToolResult.current = false;
					hasData.current = false;
					resultExplicitlyCleared.current = false;
					dataRevision.current += 1;
					snapshotCapability.current = null;
					resultCapabilityIdentity.current = null;
					displayedDataFingerprint.current = null;
					setData(null);
					setApprovalCapability(null);
					setLastResult(null);
				}
				toolCallId.current = info.id;
				toolCallName.current = info.name;
				setToolName(info.name);
				if (switchedCards) persistOpenAiData(compatTargets, null);
				if (identityChanged) {
					if (switchedCards) {
						void restoreSnapshot();
					} else if (hasCurrentLifetimeToolResult.current) {
						if (hasLiveToolOutput.current) {
							if (snapshotCapability.current) {
								void restoreSnapshot({ allowDataPresent: hasData.current }).then(
									(restored) => {
										if (restored) void persistSnapshotState();
									},
								);
							} else {
								void persistSnapshotState();
							}
						}
					} else {
						void restoreSnapshot({ allowDataPresent: hasData.current }).then(
							(restored) => {
								if (restored && shouldPersistAfterRestore())
									void persistSnapshotState();
							},
						);
					}
				}
			}
		};
		const applyOpenAiGlobals = (
			globals: unknown,
			persistInitialData = false,
		) => {
			const snapshot = readOpenAiCompatSnapshot<T>(globals);
			const compatSnapshotCapability =
				snapshotCapabilityFromOpenAiGlobals(globals);
			const includesToolOutput =
				isStructuredObject(globals) && Object.hasOwn(globals, "toolOutput");
			const nextData = hasResultData(snapshot.data)
				? (snapshot.data as T)
				: null;
			const capabilityChanged = capabilityChangesResult(
				compatSnapshotCapability,
			);
			const nextDataFingerprint =
				nextData === null ? null : resultDataFingerprint(nextData);
			const metadataLessResultChanged =
				includesToolOutput &&
				nextData !== null &&
				compatSnapshotCapability === undefined &&
				hasCurrentLifetimeToolResult.current &&
				displayedDataFingerprint.current !== null &&
				nextDataFingerprint !== displayedDataFingerprint.current;
			if (capabilityChanged || metadataLessResultChanged) {
				// ChatGPT can reuse an iframe and deliver the next result only through
				// compatibility globals. Prefer its capability as the hard boundary;
				// when metadata is stripped, differing live JSON is the fallback identity.
				resetCurrentResult();
				persistOpenAiData(compatTargets, null);
			}
			if (compatSnapshotCapability !== undefined) {
				snapshotCapability.current = compatSnapshotCapability;
				if (typeof compatSnapshotCapability === "string") {
					resultCapabilityIdentity.current = compatSnapshotCapability;
				}
			}
			const explicitlyClearsOutput =
				includesToolOutput && snapshot.data === null;
			if (includesToolOutput && nextData !== null) {
				if (
					resultExplicitlyCleared.current &&
					compatSnapshotCapability === undefined
				) {
					// Non-empty output after a clear is a new result. Do not reuse a
					// capability that arrived separately for the cleared historical card.
					snapshotCapability.current = null;
				}
				resultExplicitlyCleared.current = false;
			}
			if (includesToolOutput) {
				hasLiveToolOutput.current = true;
				if (connected && (nextData !== null || capabilityChanged)) {
					hasCurrentLifetimeToolResult.current = true;
				}
			}
			if (explicitlyClearsOutput) {
				resetResultViewState();
				dataRevision.current += 1;
				hasData.current = false;
				hasCurrentLifetimeToolResult.current = false;
				resultExplicitlyCleared.current = true;
				snapshotCapability.current = null;
				resultCapabilityIdentity.current = null;
				displayedDataFingerprint.current = null;
				setData(null);
				persistOpenAiData(compatTargets, null);
			} else if (snapshot.data !== undefined) {
				// setWidgetState echoes a widgetState-only event. Never let that
				// display-safe cache replace a live result in the current lifetime.
				if (
					nextData !== null &&
					(includesToolOutput || !hasLiveToolOutput.current)
				) {
					dataRevision.current += 1;
					displayedDataFingerprint.current = nextDataFingerprint;
					setData(nextData);
					hasData.current = true;
				}
				if ((persistInitialData || includesToolOutput) && nextData !== null) {
					persistOpenAiData(compatTargets, nextData);
				}
			}
			if (snapshot.approvalCapability !== undefined) {
				setApprovalCapability(snapshot.approvalCapability);
			}
			if (connected) {
				const shouldRestoreCapability =
					Boolean(snapshotCapability.current) &&
					(compatSnapshotCapability !== undefined ||
						(nextData !== null && includesToolOutput));
				if (!explicitlyClearsOutput && shouldRestoreCapability) {
					void restoreSnapshot({ allowDataPresent: hasData.current }).then(
						(restored) => {
							if (restored && shouldPersistAfterRestore())
								void persistSnapshotState();
						},
					);
				} else if (
					!explicitlyClearsOutput &&
					nextData !== null &&
					includesToolOutput
				) {
					if (hasCurrentLifetimeToolResult.current) {
						void persistSnapshotState();
					} else {
						void restoreSnapshot({ allowDataPresent: true }).then(
							(restored) => {
								if (restored) void persistSnapshotState();
							},
						);
					}
				} else if (!explicitlyClearsOutput && !hasData.current) {
					void restoreSnapshot();
				}
			}
		};
		const onOpenAiSetGlobals = (event: Event) => {
			const detail = (event as OpenAiSetGlobalsEvent).detail;
			if (isStructuredObject(detail) && "globals" in detail) {
				applyOpenAiGlobals(detail.globals);
			}
		};
		nextApp.addEventListener("toolresult", onToolResult);
		nextApp.addEventListener("hostcontextchanged", onHostContext);
		for (const target of compatTargets) {
			target.addEventListener(OPENAI_SET_GLOBALS_EVENT, onOpenAiSetGlobals);
		}
		// ChatGPT can split cached widget data and result metadata across the inner
		// and same-origin outer globals. Hydrate every target, applying cached or
		// metadata-only state first and explicit tool output last.
		const preloadedGlobals = [
			...new Set(
				compatTargets
					.map((target) => target.openai)
					.filter((candidate) => candidate !== undefined),
			),
		];
		for (const globals of preloadedGlobals) {
			if (!isStructuredObject(globals) || !Object.hasOwn(globals, "toolOutput"))
				applyOpenAiGlobals(globals, true);
		}
		}
		for (const globals of preloadedGlobals) {
			if (isStructuredObject(globals) && Object.hasOwn(globals, "toolOutput"))
				applyOpenAiGlobals(globals, true);
		}
		setApp(nextApp);
		void nextApp
			.connect(transport)
			.then(async () => {
				connected = true;
				const hostContext = nextApp.getHostContext();
				applyTheme(hostContext?.theme);
				const info = toolInfoFromHostContext(hostContext);
				if (info) {
					toolCallId.current = info.id;
					toolCallName.current = info.name;
					setToolName(info.name);
				}
				if (hasCurrentLifetimeToolResult.current) {
					if (hasLiveToolOutput.current) await persistSnapshotState();
				} else {
					const restored = await restoreSnapshot({
						allowDataPresent: hasData.current,
					});
					if (restored && shouldPersistAfterRestore())
						await persistSnapshotState();
				}
			})
			.catch((error) => {
				console.error("[mcp-app] failed to initialize", error);
			});

		return () => {
			nextApp.removeEventListener("toolresult", onToolResult);
			nextApp.removeEventListener("hostcontextchanged", onHostContext);
			for (const target of compatTargets) {
				target.removeEventListener(
					OPENAI_SET_GLOBALS_EVENT,
					onOpenAiSetGlobals,
				);
			}
			void transport.close();
			if (saveStateTimer.current !== null) {
				window.clearTimeout(saveStateTimer.current);
			}
			persistSnapshotStateRef.current = null;
		};
	}, [resetResultViewState]);

	const setViewState = useCallback(
		(key: string, value: ViewStateValue) => {
			if (!key || key.length > 120) return;
			const next = { ...viewStateRef.current, [key]: value };
			viewStateRef.current = next;
			viewStateRevision.current += 1;
			setViewStateValue(next);
			if (!app) return;
			if (saveStateTimer.current !== null) {
				window.clearTimeout(saveStateTimer.current);
			}
			saveStateTimer.current = window.setTimeout(() => {
				saveStateTimer.current = null;
				persistSnapshotStateRef.current?.();
			}, 250);
		},
		[app],
	);

	const callTool = async (name: string, args: ToolArgs) => {
		if (!app) {
			if (!isEmbedded) {
				console.log("[mcp-app] tools/call", name, args);
				setLastResult((last) => ({
					isError: false,
					seq: (last?.seq ?? 0) + 1,
				}));
			}
			return;
		}
		try {
			const result = await app.callServerTool({
				name,
				arguments: args,
				...(name === "resolve_lobu_approval" && approvalCapability
					? { _meta: { "lobu/approval-capability": approvalCapability } }
					: {}),
			});
			if (isStructuredObject(result.structuredContent)) {
				const nextData = result.structuredContent as T;
				resetResultViewState();
				resultExplicitlyCleared.current = false;
				snapshotCapability.current = null;
				resultCapabilityIdentity.current = null;
				hasLiveToolOutput.current = true;
				hasCurrentLifetimeToolResult.current = true;
				dataRevision.current += 1;
				hasData.current = true;
				displayedDataFingerprint.current =
					resultDataFingerprint(nextData);
				setData(nextData);
				persistOpenAiData(openAiCompatTargets(), nextData);
			}
			if (name === "resolve_lobu_approval" && result.isError !== true) {
				setApprovalCapability(null);
			}
			setLastResult((last) => ({
				isError: result.isError === true,
				seq: (last?.seq ?? 0) + 1,
			}));
		} catch {
			setLastResult((last) => ({
				isError: true,
				seq: (last?.seq ?? 0) + 1,
			}));
		}
	};

	const openLink = async (href: string) => {
		if (!isExternalHttpUrl(href)) {
			console.warn("[mcp-app] refused non-HTTP external link");
			return;
		}
		if (!app) {
			if (!isEmbedded) console.log("[mcp-app] ui/open-link", href);
			return;
		}
		try {
			const result = await app.openLink({ url: href });
			if (result.isError) console.warn("[mcp-app] host rejected external link");
		} catch {
			console.warn("[mcp-app] host rejected external link");
		}
	};

	return (
		<McpAppContext.Provider
			value={{
				data,
				toolName,
				viewState,
				setViewState,
				callTool,
				openLink,
				lastResult,
				allowSpaHostedViews,
			}}
		>
			{children}
		</McpAppContext.Provider>
	);
}

/** Mount a bundle's card as a standalone MCP App with the standard bridge. */
export function mountMcpApp<T>(opts: { devMock: T; App: FC }): void {
	const { devMock, App: View } = opts;
	createRoot(document.getElementById("root") as HTMLElement).render(
		<Provider devMock={devMock}>
			<View />
		</Provider>,
	);
}

