					(
						await tx<SnapshotRow>`
							SELECT body, tool_name
							FROM public.mcp_app_result_snapshots
							WHERE organization_id = ${identity.organizationId}
								AND client_id = ${identity.clientId}
								AND user_id = ${identity.userId}
